import{_ as t,o as a,c as i,a5 as e}from"./chunks/framework.Cooo9kuv.js";const P=JSON.parse('{"title":"程序使用环境及相关说明","description":"","frontmatter":{"标题":"940-批量pdf提取页面二维码为png图片工具-路径绘制版本","日期":"2026-05-12T00:00:00.000Z","修改日期":"2026-05-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["PDF批处理"],"标签":["PDF二维码导出PNG","PDF二维码批量提取工具","PDF二维码提取","pdf二维码识别","PDF二维码高清导出","PDF图像提取","PDF批处理工具","PDF路径绘制二维码","PDF页面二维码识别提取","二维码图片提取"]},"headers":[{"level":2,"title":"功能特点","slug":"功能特点","link":"#功能特点","children":[]},{"level":2,"title":"适用情况","slug":"适用情况","link":"#适用情况","children":[]},{"level":2,"title":"使用方法","slug":"使用方法","link":"#使用方法","children":[]},{"level":2,"title":"提取原理","slug":"提取原理","link":"#提取原理","children":[]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":2,"title":"常见问题","slug":"常见问题","link":"#常见问题","children":[]}],"relativePath":"md/PDF批处理/940-批量pdf提取页面二维码为png图片工具-路径绘制版本.md","filePath":"md/PDF批处理/940-批量pdf提取页面二维码为png图片工具-路径绘制版本.md"}'),n={name:"md/PDF批处理/940-批量pdf提取页面二维码为png图片工具-路径绘制版本.md"};function r(o,l,p,s,g,h){return a(),i("div",null,[...l[0]||(l[0]=[e('<p>用于从 PDF 文件中批量提取页面中的二维码图片，只支持路径绘制识别提取。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-5.png" alt=""></p><h2 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h2><ul><li>自动提取 PDF 页面中的二维码区域并保存为高清 PNG 图片</li><li>基于 pdf 绘图形状（路径绘制）智能识别二维码位置，并提取保存到指定文件夹下</li><li>支持批量处理一个或多个 PDF 文件</li><li>支持拖拽单个 PDF 文件或文件夹到输入框</li><li>支持递归扫描子文件夹（包含子文件夹选项）</li><li>可为每个 PDF 自动创建同名文件夹存放二维码</li><li>高 DPI 自适应，在高分屏下显示清晰</li></ul><h2 id="适用情况" tabindex="-1">适用情况 <a class="header-anchor" href="#适用情况" aria-label="Permalink to &quot;适用情况&quot;">​</a></h2><p>如下图所示，使用adobe pdf打开后，在如下位置查看页面，两个路径组成一个二维码的情况，其他情况未做测试</p><p>原理上是只要两个路径组成一个二维码的情况如下图所示的均适合。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-7.png" alt=""></p><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法&quot;">​</a></h2><ol><li><p><strong>运行程序</strong></p></li><li><p><strong>选择 PDF 路径</strong></p><ul><li>点击”浏览文件”选择单个 PDF 或包含 PDF 的文件夹</li><li>或直接拖拽 PDF 文件/文件夹到路径输入框</li></ul></li><li><p><strong>设置选项（可选）</strong></p><ul><li>☐ 包含子文件夹 — 递归扫描子目录中的 PDF</li><li>☐ 为每个PDF创建同名文件夹 — 二维码按 PDF 名称分目录存放</li></ul></li><li><p><strong>选择输出目录</strong></p><ul><li>点击”浏览”选择保存二维码图片的文件夹</li><li>或拖拽文件夹到输出目录输入框</li></ul></li><li><p><strong>开始提取</strong></p><ul><li>点击”开始提取”按钮</li><li>观察日志和进度条，支持随时点击”停止”中断</li></ul></li></ol><h2 id="提取原理" tabindex="-1">提取原理 <a class="header-anchor" href="#提取原理" aria-label="Permalink to &quot;提取原理&quot;">​</a></h2><p>本工具通过分析 PDF 页面的<strong>绘图形状</strong>定位二维码区域：</p><ul><li>扫描 PDF 页面的数据</li><li>筛选无颜色的绘图形状作为二维码候选</li><li>按成对形状定位二维码在页面中的裁剪区域</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>提取效果取决于 PDF 中二维码的绘图数据结构，部分 PDF 需手动测试</li></ul><p>**注意：**不同文件夹下序号为连续的</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-6.png" alt=""></p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: 提取的二维码图片清晰吗？</strong><br> A: 工具使用高分辨率参数放大提取，导出的二维码图片清晰可识别，支持直接用于扫码。</p><p><strong>Q: 可以同时处理多个PDF文件吗？</strong><br> A: 可以！选择包含多个PDF的文件夹，勾选”包含子文件夹”后可递归扫描子目录，一次性批量处理所有PDF文件。</p><p><strong>Q: 提取原理是什么？</strong><br> A: 通过分析PDF页面的绘图形状，筛选形状对，自动定位二维码的裁剪区域，再高分辨率导出为PNG图片。</p><p>**Q: 支持什么格式？<br> **A: 输入为PDF格式文件，输出为PNG图片格式。PDF文件可以是扫描件或电子文档。</p><h1 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h1><p><strong>1、适用的系统环境说明</strong>：</p><p>win7及以上64位windows操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：</p><p>①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p>**3、程序如何安装：**不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h1 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h1><p><strong>解压后直接使用即可，不需要安装，程序可以放在任意位置</strong></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2783.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2783.html</a></p>',33)])])}const c=t(n,[["render",r]]);export{P as __pageData,c as default};
